"""Client for the local vision model (Ternary-Bonsai served by llama.cpp's llama-server)."""

import base64

import httpx
from pydantic import BaseModel, Field

# The reply schema becomes a grammar in llama-server, so the cap is enforced while the model
# writes: a reply stuck repeating tags is cut off at the cap instead of at max_tokens.
# Parsing does not enforce it; clean_tags truncates a longer list.
MAX_TAGS = 12


class Anim(BaseModel):
    name: str
    frames: list[list[int]]


class Item(BaseModel):
    label: str
    tags: list[str] = Field(json_schema_extra={"maxItems": MAX_TAGS})
    description: str


class TagResult(BaseModel):
    tags: list[str] = Field(json_schema_extra={"maxItems": MAX_TAGS})
    description: str
    animations: list[Anim] = Field(default_factory=list)
    # Contact-sheet mode only: one entry per labelled cell.
    items: list[Item] = Field(default_factory=list)


class BonsaiClient:
    def __init__(
        self,
        base_url: str,
        transport: httpx.BaseTransport | None = None,
        timeout: float = 600.0,
    ):
        self._http = httpx.Client(base_url=base_url, transport=transport, timeout=timeout)

    def healthy(self) -> bool:
        try:
            return self._http.get("/health", timeout=5.0).status_code == 200
        except httpx.HTTPError:
            return False

    def describe(self, png: bytes, prompt: str, max_tokens: int = 1024) -> TagResult:
        """Raises httpx.HTTPError on transport/HTTP failure, ValueError on unusable output."""
        image = "data:image/png;base64," + base64.b64encode(png).decode()
        resp = self._http.post(
            "/v1/chat/completions",
            json={
                "messages": [
                    {
                        "role": "user",
                        "content": [
                            {"type": "text", "text": prompt},
                            {"type": "image_url", "image_url": {"url": image}},
                        ],
                    }
                ],
                "temperature": 0.3,
                "max_tokens": max_tokens,
                "chat_template_kwargs": {"enable_thinking": False},
                "response_format": {
                    "type": "json_schema",
                    "json_schema": {"name": "tags", "schema": TagResult.model_json_schema()},
                },
            },
        )
        resp.raise_for_status()
        try:
            choice = resp.json()["choices"][0]
            if choice.get("finish_reason") == "length":
                raise ValueError(
                    f"reply truncated: finish_reason=length at max_tokens={max_tokens}"
                )
            content = choice["message"]["content"]
        except (KeyError, IndexError, TypeError) as exc:
            raise ValueError(f"unexpected reply shape: {exc}") from exc
        # pydantic's ValidationError is a ValueError: non-JSON and schema misses land here.
        return TagResult.model_validate_json(content)

